/**
 * lib/solutions.ts
 *
 * The Solutions section: one entry per business problem we are asked to fix.
 *
 * Registry-driven, matching lib/industries.ts. Before this file the same page
 * shape existed six times as six hand-authored routes, each with its own
 * translation namespace using slightly different key names for identical
 * concepts (painEyebrow here, approachEyebrow there; sys1Title here,
 * cap1Title there). Six implementations of one page is how a section drifts,
 * and it is why no two of those pages had the same section order.
 *
 * Every entry follows the structure a consultant would actually speak in:
 *
 *   problem   what goes wrong, in the operator's own words
 *   reality   why it happens — usually structural, rarely incompetence
 *   approach  what we do about it, in order
 *   outcome   what changes afterwards
 *   scope     what is and is not included, stated plainly
 *   next      the one sensible next action
 *
 * WRITING RULES APPLIED
 * Business before technology. The reader should understand the business value
 * before any technology is named — several of these pages previously opened by
 * announcing a technology and worked backwards. None of the banned vocabulary:
 * no "AI-powered", "seamless", "leverage", "enterprise-grade", "cutting-edge",
 * "transform". No metrics we cannot evidence. No product names: the operating
 * systems are protected products and are not sold from here.
 */

export type Locale = 'de' | 'en'

interface Localised { de: string; en: string }
interface LocalisedList { de: string[]; en: string[] }

export interface Solution {
  readonly slug: string
  readonly name: Localised
  /** One line. What this is, in business terms. */
  readonly summary: Localised
  readonly problem: Localised
  readonly reality: Localised
  readonly approach: LocalisedList
  readonly outcome: LocalisedList
  /** Honest boundaries. What we do not do is as useful as what we do. */
  readonly included: LocalisedList
  readonly notIncluded: LocalisedList
  readonly next: Localised
}

